var express = require("express"); var app = express();
app.use(express.static("public")); app.use("/images", express.static("img"));
app.get("/", function (req, res) {
res.set("Cache-Control", "no-store"); var data = req.accepts();
var name = req.query.name; console.log(name);
res.end(JSON.stringify({ name: name }));
});
app.get("/image1", function (req, res) { res.set("Cache-Control", "no-store"); res.writeHead(200, { "Access-Control-Allow-Origin": "*",
});
var jsondata = { image: "https://wallpapers.com/images/featured/black-and-white-anime-girl-enx1wvpnz17kcvof.jpg" }; var stringyImage = JSON.stringify(jsondata); res.end(stringyImage);
});
app.get("/image2", function (req, res) { res.set("Cache-Control", "no-store"); res.writeHead(200, { "Access-Control-Allow-Origin": "*",
});
var jsondata = { image: "https://ar.pinterest.com/pin/706502260320876082/"
};
var stringyImage = JSON.stringify(jsondata); res.end(stringyImage);
});
app.listen(8080);
